head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.iTimer = 0;
scwin.maxval = 0;
scwin.gNewWidthSize = 0;
scwin.gDepCd;
scwin.gEmpNo;
scwin.gAcptNo;
scwin.LastJob;
scwin.gOvrdue_occr_dd;
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.gIsurCd;
scwin.gSDate; // 연체발생 시작일
scwin.gEDate; // 연체발생 종료일grd_Grid
scwin.gPeriodTp; // 기간선택

// 리사이징
scwin.gOldWidthSize = frame.width;
frame.SetEvent("onwinstat", OnWinStat);

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.cm.fn_com_isur(txb_ISUR_CD, txb_COM_NM); // 법인코드 및 법인명(회사명) 관련
        $c.cm.PanelToGroupBox(panel_1); // 검색조건 패널에 스타일 적용

        await scwin.setCode();
        scwin.init();
        const sbmOptions = {
            id : "sbm_dts_master",
            action : "/CorpBndPrincInt.do",
            ref : "",
            target : "dts_master=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
        // dts_master.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=CORPBND_PRINCINT_REGISTER_INOUT";

        dts_master.insertRow();

        // grd_Grid.ColumnProp('CHRG4','Show') = false;
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF39200.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {void}
 * @hidden N
 */
scwin.init = function() {
    // 시장구분 display none 셋팅 - 검색조건 추가시 제거
    // label_29.style.display = "none";
    // rdo_MKT_ID.style.display = "none";

    const y_day = $c.ut.cGetMinusDate2($c.ut.cGetToday("yyyymmdd"), 1);
    edt_SDate.setValue(y_day);
    edt_EDate.setValue(y_day);
    txb_ATTACH_FILE_NM.setValue("");
    // dts_FileList.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인
    dts_FileList.insertRow();

    // 삭제버튼 - 선택한 시장구분의 데이터를 삭제한다.(테스트를 위해 만들어 놓은 버튼으로써 항상 show false)로 처리
    btn_Del.hide();
    // 총회사수 - 총회사수를 구할 경우 정렬이 깨지는 현상이 있어 show false 처리
    txb_companyCnt.hide();

    // 상장구분
    combo_stat.setDisabled(false);
    combo_stat.addClass("TopCondition_01");
    if (js_market === "9" || js_market === "4") {
        // 시장구분
        rdo_MKT_ID.setDisabled(false);
        rdo_MKT_ID.addClass("TopCondition_Blue");

        // 채권상장여부
        combo_bnd_stat.setDisabled(false);
        combo_bnd_stat.addClass("TopCondition_01");

        // 주권상장구분
        combo_stat.setSelectedIndex(0);
        // 채권상장여부
        combo_bnd_stat.setSelectedIndex(1);
        label_9.hide();
    } else {
        // 콘트롤 잠그기

        // 시장구분
        rdo_MKT_ID.setDisabled(true);
        label_29.hide();
        rdo_MKT_ID.hide();

        // 주권상장구분
        combo_stat.setSelectedIndex(1);
        // 채권상장여부
        combo_bnd_stat.setSelectedIndex(0);

        // combo_bnd_stat.Enable = false;
        // showObj(label_1, false);
        // showObj(combo_bnd_stat, false);

        // 상장구분
        // combo_stat.Index = 1;
        // combo_stat.Enable = false;
        // showObj(label_2, false);
        // showObj(combo_stat, false);

    }
    if (js_market === '1') {
        // 유가
        $c.cm.setColumnProp(grd_Grid, 'MAJOR_COMPANY_YN', 'Name', '(유)대규모기업여부');
        rdo_MKT_ID.setValue(js_market);
    } else if (js_market === '2') {
        // 코스닥
        $c.cm.setColumnProp(grd_Grid, 'MAJOR_COMPANY_YN', 'Name', '(코)대기업여부');
        rdo_MKT_ID.setValue(js_market);
    } else if (js_market === '6') {
        // 코넥스
        $c.cm.setColumnProp(grd_Grid, 'MAJOR_COMPANY_YN', 'Show', false);
        rdo_MKT_ID.setValue(js_market);
    } else if (js_market === '4') {
        // 채권상장공시팀
        $c.cm.setColumnProp(grd_Grid, 'MAJOR_COMPANY_YN', 'Name', '대기업여부');
        rdo_MKT_ID.setValue("0");
    } else if (js_market === '9') {
        // 시스템
        // label_29.style.display = "";
        // rdo_MKT_ID.style.display = "";
        rdo_MKT_ID.setValue(0);
    } else {
        rdo_MKT_ID.setValue("0");
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name txb_ISUR_CD_onkeyup
 * @description txb_ISUR_CD 키 입력 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_ISUR_CD_onkeyup = function() {
    try {
        if (txb_ISUR_CD.getValue() === "") {
            Grd_com_isur.style.display = "none";
        } else {
            if (window.event.keyCode === 40) {
                // 아래화살표눌렀을때 그리드로 포커스
                Grd_com_isur.focus();
            } else {
                $c.cm.fn_com_isur_nm(window.event.keyCode);
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF39200.txb_ISUR_CD_onkeyup" });
    }
};

/**
 * @method
 * @name txb_ISUR_CD_onfocus
 * @description txb_ISUR_CD 포커스 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_ISUR_CD_onfocus = function() {
    try {
        Grd_com_isur.style.display = "none";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF39200.txb_ISUR_CD_onfocus" });
    }
};

/**
 * @method
 * @name txb_ISUR_CD_onblur
 * @description txb_ISUR_CD 포커스 이탈 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_ISUR_CD_onblur = function() {
    try {
        if (stFocusGrid === false) {
            Grd_com_isur.style.display = "none";
        }
        if (txb_ISUR_CD.getValue() === "") {
            txb_COM_NM.setValue("");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF39200.txb_ISUR_CD_onblur" });
    }
};

/**
 * @method
 * @name btn_ISUR_CD_onclick
 * @description btn_ISUR_CD 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_ISUR_CD_onclick = function() {
    try {
        if (js_market === "4") {
            scwin.fn_GetPar = scwin.getParIsurCd;
            scwin.fn_SetPar = scwin.setParIsurCd;
            $c.bns.fn_PopIsurSearch(btn_ISUR_CD);
        } else if (js_market === "9") {
            scwin.fn_GetPar = scwin.getParIsurCd;
            scwin.fn_SetPar = scwin.setParIsurCd;
            $c.bns.fn_PopIsurSearch(btn_ISUR_CD);
        } else {
            $c.cm.IsurcdSearch(txb_ISUR_CD, txb_COM_NM); // 법인명 검색 팝업

        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF39200.btn_ISUR_CD_onclick" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnKeyPress
 * @description Grd com isur On Key Press 처리
 * @param {*} kcode kcode
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    try {
        if (kcode === '13') {
            $c.cm.fn_com_Confirm_set();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF39200.Grd_com_isur_OnKeyPress" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnDblClick
 * @description Grd_com_isur 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    try {
        $c.cm.fn_com_Confirm_set();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF39200.Grd_com_isur_OnDblClick" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnClick
 * @description Grd_com_isur 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnClick = function(row, colid) {
    try {
        Grd_com_isur.style.display = "";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF39200.Grd_com_isur_OnClick" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnSetFocus
 * @description Grd com isur On Set Focus 처리
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnSetFocus = function() {
    try {
        stFocusGrid = true;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF39200.Grd_com_isur_OnSetFocus" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnKillFocus
 * @description Grd_com_isur 포커스 이탈 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnKillFocus = function() {
    try {
        stFocusGrid = false;
        Grd_com_isur.style.display = "none";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF39200.Grd_com_isur_OnKillFocus" });
    }
};

/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function() {
    try {
        await scwin.search(); // 조회 버튼
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF39200.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name dts_Grid_OnLoadError
 * @description dts_Grid 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_Grid_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_Grid);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF39200.dts_Grid_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_Grid_OnLoadCompleted
 * @description dts_Grid 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_Grid_OnLoadCompleted = function(rowcount) {
    try {
        txb_TotalCnt.setValue("총건수 : " + rowcount);
        cnt = dts_Grid.getCellData(0, "COM_CNT");
        // alert("rowcount : " + rowcount + " : cnt : " + cnt);
        if (isNaN(cnt)) {
            cnt = "0";
        }
        // txb_companyCnt.value = "총회사수 : " + cnt;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF39200.dts_Grid_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name btn_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Excel_onclick = function() {
    try {
        $c.stf.doLogSave('ULDSTF39200.xml', SCREN_PROCS_TP_CD_07);
        $c.data.downloadGridViewExcel(grd_Grid, {fileName: "사채원리금 연체정보", type: "8"}); // 엑셀 다운로드
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF39200.btn_Excel_onclick" });
    }
};

/**
 * @method
 * @name cmb_TeamList_onselchange
 * @description cmb_TeamList onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_TeamList_onselchange = function() {
    try {
        scwin.gDepCd = $c.cp.valueOfIndex(cmb_TeamList, "VALUE", cmb_TeamList.getSelectedIndex());
        if (scwin.gDepCd === '' || scwin.gDepCd === 'UPTEAM') {
            cmb_EmpList.setValue('');
        }
        dts_emp.UseFilter = true;
        dts_emp.Filter();
        dts_emp.sort("DEP_CD", 0);
        // dts_emp.sort(); // W-Craft 주석처리
        if (scwin.gDepCd !== '' && scwin.gDepCd !== 'UPTEAM') {
            cmb_EmpList.trigger("onclick");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF39200.cmb_TeamList_onselchange" });
    }
};

/**
 * @method
 * @name dts_dep_OnLoadCompleted
 * @description dts_dep 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_dep_OnLoadCompleted = function(rowcount) {
    try {
        if (js_dep_cd.substring(0, 2) === '26' || js_dep_cd.substring(0, 2) === '34') {
            $c.stf.copyDataSet(dts_dep, dts_dep1);
            scwin.addDsclTeamAll(rowcount);
            cmb_TeamList.setValue('UPTEAM');
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF39200.dts_dep_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_emp_OnFilter
 * @description emp On Filter 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.dts_emp_OnFilter = function(row) {
    try {
        //  부서코드에  해당하는 사원을 가져온다.
        if (scwin.gDepCd === "" || scwin.gDepCd === "UPTEAM") {
            // 전체일 경우 모두 보여준다.
            return true;
        } else {
            if (dts_emp.getCellData(row, "dep_cd") === scwin.gDepCd ||
                dts_emp.getCellData(row, "dep_cd") === "UPTEAM" ||
                dts_emp.getCellData(row, "dep_cd") === "") {
                return true;
            } else {
                return false;
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF39200.dts_emp_OnFilter" });
    }
};

/**
 * @method
 * @name MxDataSet_com_isur_OnFilter
 * @description Mx Data Set com isur On Filter 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    try {
        if (skw !== "" && foColum === "1") {
            f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
            f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
            if (f1.indexOf(skw) !== -1 || f2.indexOf(skw) !== -1) return true;

            else return false;
        } else {
            return true;
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF39200.MxDataSet_com_isur_OnFilter" });
    }
};

