 */
scwin.selectAttach = function() {
    if (file.getValue() === "") return;
    txb_ATTACH_FILE_NM.setValue(file.getValue());
    dts_FileList.setCellData(1, "fileInfo", file.getValue());
    dts_FileList.setCellData(1, "fileUrl", file.getValue());
};

/**
 * @method
 * @name save
 * @description 엑셀파일저장
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function() {
    dts_master.setCellData(1, "REG_EMP_NO", js_emp_no);
    const file_nm = file.getValue();
    if (file_nm === "") {
        msg = $c.stf.getMessageParam("MSG-A005", "파일업로드");
        await $c.win.alert(msg);
        txb_ATTACH_FILE_NM.focus();
        return;
    }
    const suffix = file_nm.substring(file_nm.lastIndexOf(".") + 1);
    if (suffix !== 'xls') {
        await $c.win.alert("확장자 'xls' 만 가능합니다.");
        return;
    }
    if (!confirm("저장하시겠습니까?")) {
        return;
    }
    scwin.LastJob = "엑셀저장";
    trs_Save.Action = "/CorpBndPrincInt.do?method=registerCorpBndPrincInt" + "&SCREN_ID=" + 'ULDSTF39200.xml' + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInputMaster=dts_master,I:pFile=dts_FileList)";
    trs_Save.post();
};

